//! Differential replay of the P4-B brain fixtures
//! (`fixtures/intel/{minhash,pooling,ranking,regret,sketch,spellfix,state}.jsonl`,
//! generated by RUNNING the Node oracle under `scripts/fixture-brain-*.js`).
//!
//! Every fixture line is `{"fn", "input", "output" | "error"}`; the Rust port
//! is driven with the same inputs and compared recursively:
//!  - numbers: integers byte-exact (i64/u64); f64 fields exact when equal,
//!    otherwise `marfim_brain::util::ulp_close` (<= 1 ulp) — EXCEPT the
//!    `_probe_*` lines (transcendental / pyRound / pyFloatRepr / MT19937
//!    engine pins), which demand bit-exact floats;
//!  - strings byte-exact, null -> None, bools, objects key-wise
//!    (order-insensitive), arrays order-sensitive.

use std::collections::BTreeMap;

use marfim_brain::brain::{minhash, pooling, ranking, regret, sketch, spellfix, state};
use marfim_brain::util::ulp_close;
use serde_json::{json, Value};

// ------------------------------------------------------------------ harness

fn load_fixture(name: &str) -> Vec<Value> {
    let path = format!(
        "{}/../../fixtures/intel/{name}.jsonl",
        env!("CARGO_MANIFEST_DIR")
    );
    let text =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("fixture {name}: {e} ({path})"));
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| serde_json::from_str(l).unwrap_or_else(|e| panic!("{name} line `{l}`: {e}")))
        .collect()
}

/// JSON rendering of a JS number the way `JSON.stringify` emits it
/// (integral -> bare integer, -0 -> 0, NaN/Infinity -> null).
fn jnum(x: f64) -> Value {
    if !x.is_finite() {
        return Value::Null;
    }
    if x == 0.0 {
        return json!(0i64);
    }
    if x.fract() == 0.0 && x.abs() < 9.007_199_254_740_992e15 {
        return json!(x as i64);
    }
    match serde_json::Number::from_f64(x) {
        Some(n) => Value::Number(n),
        None => Value::Null,
    }
}

fn compare(path: &str, oracle: &Value, rust: &Value, exact: bool) -> Result<(), String> {
    match (oracle, rust) {
        (Value::Null, Value::Null) => Ok(()),
        (Value::Bool(a), Value::Bool(b)) if a == b => Ok(()),
        (Value::String(a), Value::String(b)) if a == b => Ok(()),
        (Value::Number(_), Value::Number(_)) => num_eq(path, oracle, rust, exact),
        (Value::Array(a), Value::Array(b)) => {
            if a.len() != b.len() {
                return Err(format!("{path}: array length {} vs {}", a.len(), b.len()));
            }
            for (i, (x, y)) in a.iter().zip(b.iter()).enumerate() {
                compare(&format!("{path}[{i}]"), x, y, exact)?;
            }
            Ok(())
        }
        (Value::Object(a), Value::Object(b)) => {
            for key in a.keys() {
                if !b.contains_key(key) {
                    return Err(format!("{path}: missing key `{key}` on the Rust side"));
                }
            }
            for key in b.keys() {
                if !a.contains_key(key) {
                    return Err(format!("{path}: extra key `{key}` on the Rust side"));
                }
            }
            for key in a.keys() {
                compare(&format!("{path}.{key}"), &a[key], &b[key], exact)?;
            }
            Ok(())
        }
        _ => Err(format!("{path}: type mismatch {oracle:?} vs {rust:?}")),
    }
}

fn num_eq(path: &str, oracle: &Value, rust: &Value, exact: bool) -> Result<(), String> {
    if let (Some(a), Some(b)) = (oracle.as_i64(), rust.as_i64()) {
        return if a == b {
            Ok(())
        } else {
            Err(format!("{path}: integer {a} vs {b}"))
        };
    }
    if let (Some(a), Some(b)) = (oracle.as_u64(), rust.as_u64()) {
        return if a == b {
            Ok(())
        } else {
            Err(format!("{path}: integer {a} vs {b}"))
        };
    }
    match (oracle.as_f64(), rust.as_f64()) {
        (Some(a), Some(b)) => {
            if a == b || (a.is_nan() && b.is_nan()) {
                Ok(())
            } else if exact {
                Err(format!(
                    "{path}: probe floats must be bit-exact: {a} vs {b}"
                ))
            } else if ulp_close(a, b) {
                Ok(())
            } else {
                Err(format!("{path}: floats beyond 1 ulp: {a} vs {b}"))
            }
        }
        _ => Err(format!("{path}: number shapes {oracle:?} vs {rust:?}")),
    }
}

type Dispatch = fn(&str, &[Value]) -> Result<Value, String>;

fn replay(module: &str, dispatch: Dispatch) -> usize {
    let cases = load_fixture(module);
    let mut checked = 0usize;
    for case in &cases {
        let fname = case
            .get("fn")
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("{module}: missing fn in {case}"));
        let input = case
            .get("input")
            .and_then(Value::as_array)
            .unwrap_or_else(|| panic!("{module}/{fname}: missing input array"));
        // probes pin engine-identical values for the EXACT inlined helpers
        // (pyRound, pyFloatRepr, MT19937); the two transcendental probes use
        // the documented <=1-ulp tolerance (V8's Math.exp/10**z and the
        // platform libm can differ by 1 ulp on some inputs — see the ranking
        // module docs)
        let is_probe = fname.starts_with("_probe");
        let exact = is_probe && !matches!(fname, "_probe_exp" | "_probe_pow10");
        let rust_result = dispatch(fname, input);
        if let Some(expected) = case.get("output") {
            let actual = rust_result
                .unwrap_or_else(|e| panic!("{module}/{fname} {input:?}: unexpected error: {e}"));
            compare(&format!("{module}/{fname}"), expected, &actual, exact)
                .unwrap_or_else(|e| panic!("{module}/{fname} {input:?}: {e}"));
        } else if let Some(expected_err) = case.get("error") {
            let err = dispatch(fname, input).err().unwrap_or_else(|| {
                panic!("{module}/{fname} {input:?}: expected error, got success")
            });
            assert_eq!(
                err,
                expected_err
                    .as_str()
                    .unwrap_or_else(|| panic!("non-string error")),
                "{module}/{fname} {input:?}"
            );
        } else {
            panic!("{module}/{fname}: fixture has neither output nor error");
        }
        checked += 1;
    }
    assert!(checked > 0, "{module}: no fixture lines loaded");
    checked
}

// ------------------------------------------------------------------- inputs

fn f64_of(v: &Value) -> f64 {
    v.as_f64().unwrap_or(f64::NAN)
}

fn usize_of(v: Option<&Value>, default: u64) -> usize {
    v.and_then(Value::as_u64).unwrap_or(default) as usize
}

fn str_pairs(v: &Value) -> Vec<(String, String)> {
    v.as_array()
        .map(|a| {
            a.iter()
                .map(|p| {
                    let arr = p.as_array().unwrap_or_else(|| panic!("pair {p}"));
                    (
                        arr.first()
                            .and_then(Value::as_str)
                            .unwrap_or_default()
                            .to_string(),
                        arr.get(1)
                            .and_then(Value::as_str)
                            .unwrap_or_default()
                            .to_string(),
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}

fn str_f64_map(v: Option<&Value>) -> Option<BTreeMap<String, f64>> {
    v.map(|m| {
        m.as_object()
            .map(|o| {
                o.iter()
                    .map(|(k, v)| (k.clone(), f64_of(v)))
                    .collect::<BTreeMap<_, _>>()
            })
            .unwrap_or_default()
    })
}

fn pair_map(v: &Value) -> BTreeMap<String, [f64; 2]> {
    v.as_object()
        .map(|o| {
            o.iter()
                .map(|(k, val)| {
                    let arr = val.as_array().unwrap_or_else(|| panic!("arm {val}"));
                    (
                        k.clone(),
                        [
                            arr.first().and_then(Value::as_f64).unwrap_or(0.0),
                            arr.get(1).and_then(Value::as_f64).unwrap_or(0.0),
                        ],
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}

fn pooled_from(v: &Value) -> pooling::PooledArms {
    let obj = v.as_object().unwrap_or_else(|| panic!("pooled {v}"));
    let strings = |key: &str| -> Vec<String> {
        obj.get(key)
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(Value::as_str)
                    .map(String::from)
                    .collect()
            })
            .unwrap_or_default()
    };
    pooling::PooledArms {
        mu0: obj.get("mu0").and_then(Value::as_f64).unwrap_or(0.0),
        k0: obj.get("k0").and_then(Value::as_f64).unwrap_or(0.0),
        tau2: obj.get("tau2").and_then(Value::as_f64).unwrap_or(0.0),
        n_arms: usize_of(obj.get("n_arms"), 0),
        evidence_arms: usize_of(obj.get("evidence_arms"), 0),
        no_evidence_arms: strings("no_evidence_arms"),
        total_evidence: obj
            .get("total_evidence")
            .and_then(Value::as_f64)
            .unwrap_or(0.0),
        pooled: obj.get("pooled").and_then(Value::as_bool).unwrap_or(false),
        note: obj.get("note").and_then(Value::as_str).map(String::from),
    }
}

// ------------------------------------------------------------------ minhash

fn dispatch_minhash(fname: &str, input: &[Value]) -> Result<Value, String> {
    match fname {
        "_P" => Ok(json!(minhash::_P.to_string())),
        "_MAX" => Ok(json!(minhash::_MAX)),
        "_perms" => Ok(json!(minhash::_perms(usize_of(input.first(), 0), 42)
            .iter()
            .map(|(a, b)| vec![a.to_string(), b.to_string()])
            .collect::<Vec<_>>())),
        "_probe_mt_getrandbits61" => {
            let seed = input.first().and_then(Value::as_u64).unwrap_or(0);
            let draws = usize_of(input.get(1), 0);
            let mut rng = minhash::mt19937::Mt19937::new(seed);
            Ok(json!((0..draws)
                .map(|_| rng.getrandbits(61).to_string())
                .collect::<Vec<_>>()))
        }
        "signature" => {
            let text = input.first().and_then(Value::as_str).unwrap_or("");
            let num_perm = usize_of(input.get(1), 64);
            Ok(match minhash::signature(text, num_perm) {
                Some(sig) => json!(sig),
                None => Value::Null,
            })
        }
        "jaccard" => {
            let sig = |v: Option<&Value>| -> Vec<u32> {
                v.and_then(Value::as_array)
                    .map(|a| {
                        a.iter()
                            .filter_map(Value::as_u64)
                            .map(|x| x as u32)
                            .collect()
                    })
                    .unwrap_or_default()
            };
            let a = sig(input.first());
            let b = sig(input.get(1));
            Ok(jnum(minhash::jaccard(&a, &b)))
        }
        "nearDuplicates" => {
            let docs: BTreeMap<String, String> = input
                .first()
                .and_then(Value::as_object)
                .map(|o| {
                    o.iter()
                        .map(|(k, v)| (k.clone(), v.as_str().unwrap_or_default().to_string()))
                        .collect()
                })
                .unwrap_or_default();
            let threshold = input.get(1).and_then(Value::as_f64).unwrap_or(0.8);
            let bands = usize_of(input.get(2), 16);
            let out: Vec<Value> = minhash::near_duplicates(&docs, threshold, bands)
                .iter()
                .map(|(a, b, s)| json!([a, b, minhash::score_to_json(*s)]))
                .collect();
            Ok(Value::Array(out))
        }
        _ => Err(format!("unknown minhash fn `{fname}`")),
    }
}

// ------------------------------------------------------------------ pooling

fn dispatch_pooling(fname: &str, input: &[Value]) -> Result<Value, String> {
    match fname {
        "FLAT_PRIOR_ALPHA" => Ok(json!(pooling::FLAT_PRIOR_ALPHA)),
        "FLAT_PRIOR_BETA" => Ok(json!(pooling::FLAT_PRIOR_BETA)),
        "MIN_K0" => Ok(json!(pooling::MIN_K0)),
        "_probe_pyRound" => {
            let x = f64_of(input.first().unwrap_or(&Value::Null));
            let digits = input.get(1).and_then(Value::as_i64).unwrap_or(0) as i32;
            Ok(jnum(pooling::py_round(x, digits)))
        }
        "poolArms" => {
            let arms = pair_map(input.first().unwrap_or(&Value::Null));
            let pa = input
                .get(1)
                .and_then(Value::as_f64)
                .unwrap_or(pooling::FLAT_PRIOR_ALPHA);
            let pb = input
                .get(2)
                .and_then(Value::as_f64)
                .unwrap_or(pooling::FLAT_PRIOR_BETA);
            pooling::pool_arms(&arms, pa, pb)
                .map(|p| p.to_json())
                .map_err(|e| e.to_string())
        }
        "hierarchicalPrior" => {
            let pooled = pooled_from(input.first().unwrap_or(&Value::Null));
            Ok(pooling::hierarchical_prior(&pooled).to_json())
        }
        "shrunkMean" => {
            let alpha = f64_of(input.first().unwrap_or(&Value::Null));
            let beta = f64_of(input.get(1).unwrap_or(&Value::Null));
            let pooled = pooled_from(input.get(2).unwrap_or(&Value::Null));
            let pa = input
                .get(3)
                .and_then(Value::as_f64)
                .unwrap_or(pooling::FLAT_PRIOR_ALPHA);
            let pb = input
                .get(4)
                .and_then(Value::as_f64)
                .unwrap_or(pooling::FLAT_PRIOR_BETA);
            Ok(pooling::shrunk_mean(alpha, beta, &pooled, pa, pb).to_json())
        }
        _ => Err(format!("unknown pooling fn `{fname}`")),
    }
}

// ------------------------------------------------------------------ ranking

fn dispatch_ranking(fname: &str, input: &[Value]) -> Result<Value, String> {
    match fname {
        "BASE_RATING" => Ok(json!(ranking::BASE_RATING)),
        "DEFAULT_ELO_K" => Ok(json!(ranking::DEFAULT_ELO_K)),
        "MIN_COMPARISONS" => Ok(json!(ranking::MIN_COMPARISONS)),
        "_probe_exp" => Ok(jnum(f64_of(input.first().unwrap_or(&Value::Null)).exp())),
        "_probe_pow10" => Ok(jnum(
            10f64.powf(f64_of(input.first().unwrap_or(&Value::Null))),
        )),
        "bradleyTerry" => {
            let pairs = str_pairs(input.first().unwrap_or(&Value::Null));
            let iterations = usize_of(input.get(1), 200);
            let step = input.get(2).and_then(Value::as_f64).unwrap_or(0.05);
            ranking::bradley_terry(&pairs, iterations, step)
                .map(|r| r.to_json())
                .map_err(|e| e.to_string())
        }
        "eloLadder" => {
            let init = input.first().unwrap_or(&Value::Null);
            let games = str_pairs(input.get(1).unwrap_or(&Value::Null));
            let names: Option<Vec<String>> = match input.get(2) {
                Some(Value::Array(a)) => Some(
                    a.iter()
                        .filter_map(Value::as_str)
                        .map(String::from)
                        .collect(),
                ),
                _ => None,
            };
            let ratings = str_f64_map(init.get("ratings"));
            let counts = str_f64_map(init.get("counts"));
            let k = input
                .get(3)
                .and_then(Value::as_f64)
                .unwrap_or(ranking::DEFAULT_ELO_K);
            let mut elo = ranking::EloLadder::new(ratings.as_ref(), counts.as_ref(), k);
            for (w, l) in &games {
                elo.observe(w, l).map_err(|e| e.to_string())?;
            }
            // capture order matters: toDict, then ladder, then expected —
            // ladder/expected insert defaults into the maps, exactly like the
            // oracle's fixture harness
            let to_dict = elo.to_dict();
            let ladder: Vec<Value> = elo
                .ladder(names.as_deref())
                .iter()
                .map(ranking::LadderRow::to_json)
                .collect();
            let expected_ab = elo.expected("a", "b");
            Ok(json!({ "toDict": to_dict, "ladder": ladder, "expected_ab": jnum(expected_ab) }))
        }
        "eloFromDictContinue" => {
            // fixture construction: fresh ladder, observe a>b then b>c, then
            // from_dict(to_dict) and the input games on top of the rebuild
            let mut elo = ranking::EloLadder::default();
            elo.observe("a", "b").map_err(|e| e.to_string())?;
            elo.observe("b", "c").map_err(|e| e.to_string())?;
            let mut round = ranking::EloLadder::from_dict(Some(&elo.to_dict()));
            for (w, l) in str_pairs(input.first().unwrap_or(&Value::Null)) {
                round.observe(&w, &l).map_err(|e| e.to_string())?;
            }
            let ladder: Vec<Value> = round
                .ladder(None)
                .iter()
                .map(ranking::LadderRow::to_json)
                .collect();
            Ok(json!({ "toDict": round.to_dict(), "ladder": ladder }))
        }
        "eloObserveSelf" => {
            let mut elo = ranking::EloLadder::default();
            for (w, l) in str_pairs(input.first().unwrap_or(&Value::Null)) {
                elo.observe(&w, &l).map_err(|e| e.to_string())?;
            }
            Ok(Value::Null) // unreachable: every game here is self-play
        }
        "ladderReport" => {
            let pairs = str_pairs(input.first().unwrap_or(&Value::Null));
            let elo = match input.get(1) {
                Some(v @ Value::Object(_)) => Some(ranking::EloLadder::from_dict(Some(v))),
                _ => None,
            };
            ranking::ladder_report(&pairs, elo)
                .map(|r| r.to_json())
                .map_err(|e| e.to_string())
        }
        _ => Err(format!("unknown ranking fn `{fname}`")),
    }
}

// ------------------------------------------------------------------- regret

fn dispatch_regret(fname: &str, input: &[Value]) -> Result<Value, String> {
    match fname {
        "FLAT_PRIOR" => Ok(json!(regret::FLAT_PRIOR)),
        "auditFromArms" => {
            let arms = pair_map(input.first().unwrap_or(&Value::Null));
            let prior = input
                .get(1)
                .and_then(Value::as_f64)
                .unwrap_or(regret::FLAT_PRIOR);
            Ok(regret::audit_from_arms(&arms, prior).to_json())
        }
        "auditFromDraws" => {
            // oracle contract: reward === 1 || reward === true is a win —
            // booleans normalise to 1.0/0.0, other non-numbers to 0.0
            let draws: Vec<(String, f64)> = input
                .first()
                .and_then(Value::as_array)
                .map(|a| {
                    a.iter()
                        .map(|d| {
                            let arr = d.as_array().unwrap_or_else(|| panic!("draw {d}"));
                            let arm = arr
                                .first()
                                .and_then(Value::as_str)
                                .unwrap_or_default()
                                .to_string();
                            let reward = match arr.get(1) {
                                Some(Value::Bool(b)) => {
                                    if *b {
                                        1.0
                                    } else {
                                        0.0
                                    }
                                }
                                Some(v) => v.as_f64().unwrap_or(0.0),
                                None => 0.0,
                            };
                            (arm, reward)
                        })
                        .collect()
                })
                .unwrap_or_default();
            Ok(regret::audit_from_draws(&draws).to_json())
        }
        _ => Err(format!("unknown regret fn `{fname}`")),
    }
}

// ------------------------------------------------------------------- sketch

fn ss_adds(v: &Value) -> Vec<(String, f64)> {
    v.as_array()
        .map(|a| {
            a.iter()
                .map(|d| {
                    let arr = d.as_array().unwrap_or_else(|| panic!("add {d}"));
                    (
                        arr.first()
                            .and_then(Value::as_str)
                            .unwrap_or_default()
                            .to_string(),
                        arr.get(1).and_then(Value::as_f64).unwrap_or(1.0),
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}

fn digest_adds(v: &Value) -> Vec<(f64, f64)> {
    v.as_array()
        .map(|a| {
            a.iter()
                .map(|d| {
                    let arr = d.as_array().unwrap_or_else(|| panic!("add {d}"));
                    (
                        arr.first().and_then(Value::as_f64).unwrap_or(0.0),
                        arr.get(1).and_then(Value::as_f64).unwrap_or(1.0),
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}

fn dispatch_sketch(fname: &str, input: &[Value]) -> Result<Value, String> {
    match fname {
        "SS_MAX_ITEMS" => Ok(json!(sketch::SS_MAX_ITEMS)),
        "DIGEST_MAX_VALUES" => Ok(json!(sketch::DIGEST_MAX_VALUES)),
        "spaceSaving" => {
            let k = usize_of(input.first(), 10);
            let mut ss = sketch::SpaceSaving::new(k).map_err(|e| e.to_string())?;
            for (key, weight) in ss_adds(input.get(1).unwrap_or(&Value::Null)) {
                ss.add(&key, weight);
            }
            let hitters: Vec<Value> = ss
                .heavy_hitters()
                .iter()
                .map(sketch::HeavyHitter::to_json)
                .collect();
            Ok(json!({ "state": ss.to_json(), "hitters": hitters }))
        }
        "spaceSavingNew" => {
            let k = usize_of(input.first(), 0);
            sketch::SpaceSaving::new(k)
                .map(|_| Value::Null)
                .map_err(|e| e.to_string())
        }
        "spaceSavingMerge" => {
            let k = usize_of(input.first(), 10);
            let build = |adds: &Value| -> Result<sketch::SpaceSaving, String> {
                let mut ss = sketch::SpaceSaving::new(k).map_err(|e| e.to_string())?;
                for (key, weight) in ss_adds(adds) {
                    ss.add(&key, weight);
                }
                Ok(ss)
            };
            let left = build(input.get(1).unwrap_or(&Value::Null))?;
            let right = build(input.get(2).unwrap_or(&Value::Null))?;
            let merged = left.merge(&right).map_err(|e| e.to_string())?;
            let hitters: Vec<Value> = merged
                .heavy_hitters()
                .iter()
                .map(sketch::HeavyHitter::to_json)
                .collect();
            Ok(json!({ "state": merged.to_json(), "hitters": hitters }))
        }
        "tdigest" => {
            let delta = f64_of(input.first().unwrap_or(&Value::Null));
            let cap = usize_of(input.get(1), 10_000);
            let adds = digest_adds(input.get(2).unwrap_or(&Value::Null));
            let queries: Vec<f64> = input
                .get(3)
                .and_then(Value::as_array)
                .map(|a| a.iter().filter_map(Value::as_f64).collect())
                .unwrap_or_default();
            let mut td = sketch::TDigest::new(delta, cap);
            for (v, w) in adds {
                td.add(v, w);
            }
            let before_state = td.to_json();
            let qvals: Vec<Value> = queries
                .iter()
                .map(|q| td.quantile(*q).map(jnum).unwrap_or(Value::Null))
                .collect();
            let after_state = td.to_json();
            let (merge_state, merge_quantiles) = match input.get(4) {
                Some(m) if m.is_object() => {
                    let m_delta = m.get("delta").and_then(Value::as_f64).unwrap_or(100.0);
                    let m_cap = usize_of(m.get("cap"), 10_000);
                    let mut other = sketch::TDigest::new(m_delta, m_cap);
                    for (v, w) in digest_adds(m.get("adds").unwrap_or(&Value::Null)) {
                        other.add(v, w);
                    }
                    let mut merged = td.merge(&other);
                    let m_queries: Vec<f64> = m
                        .get("queries")
                        .and_then(Value::as_array)
                        .map(|a| a.iter().filter_map(Value::as_f64).collect())
                        .unwrap_or_default();
                    let mq: Vec<Value> = m_queries
                        .iter()
                        .map(|q| merged.quantile(*q).map(jnum).unwrap_or(Value::Null))
                        .collect();
                    let state_after = merged.to_json();
                    (Some(state_after), Some(Value::Array(mq)))
                }
                _ => (None, None),
            };
            Ok(json!({
                "beforeState": before_state,
                "qvals": qvals,
                "afterState": after_state,
                "mergeState": merge_state,
                "mergeQuantiles": merge_quantiles,
            }))
        }
        "sizingReport" => {
            let sizes: Vec<f64> = input
                .first()
                .and_then(Value::as_array)
                .map(|a| a.iter().filter_map(Value::as_f64).collect())
                .unwrap_or_default();
            let keys: Option<Vec<String>> = match input.get(1) {
                Some(Value::Array(a)) => Some(
                    a.iter()
                        .filter_map(Value::as_str)
                        .map(String::from)
                        .collect(),
                ),
                _ => None,
            };
            let k = usize_of(input.get(2), 8);
            let quantiles: Option<Vec<f64>> = match input.get(3) {
                Some(Value::Array(a)) => Some(a.iter().filter_map(Value::as_f64).collect()),
                _ => None,
            };
            sketch::sizing_report(&sizes, keys.as_deref(), k, quantiles.as_deref())
                .map_err(|e| e.to_string())
        }
        "renderSizing" => Ok(json!(sketch::render_sizing(
            input.first().unwrap_or(&Value::Null)
        ))),
        _ => Err(format!("unknown sketch fn `{fname}`")),
    }
}

// ----------------------------------------------------------------- spellfix

fn corpus_of(v: &Value, key: &str) -> Vec<String> {
    v.get(key)
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(Value::as_str)
                .map(String::from)
                .collect()
        })
        .unwrap_or_default()
}

fn spell_index_output(ix: &spellfix::SpellIndex, top: usize) -> Value {
    let suggest: Vec<Value> = ix
        .suggest(top)
        .iter()
        .map(spellfix::Suggestion::to_json)
        .collect();
    let counts = ix.to_json();
    json!({
        "counts": counts.get("counts").cloned().unwrap_or(Value::Null),
        "suggest": suggest,
    })
}

fn spell_params(v: &Value) -> (usize, i64, i64, usize) {
    (
        usize_of(v.get("min_word_len"), 3),
        v.get("rare_max").and_then(Value::as_i64).unwrap_or(1),
        v.get("common_min").and_then(Value::as_i64).unwrap_or(5),
        usize_of(v.get("top"), 20),
    )
}

fn dispatch_spellfix(fname: &str, input: &[Value]) -> Result<Value, String> {
    match fname {
        "deletes" => {
            let word = input.first().and_then(Value::as_str).unwrap_or("");
            let depth = usize_of(input.get(1), 2);
            Ok(json!(spellfix::deletes(word, depth)))
        }
        "spellIndex" => {
            let spec = input.first().unwrap_or(&Value::Null);
            let (min_len, rare_max, common_min, top) = spell_params(spec);
            let corpus = corpus_of(spec, "corpus");
            let refs: Vec<&str> = corpus.iter().map(String::as_str).collect();
            let mut ix = spellfix::SpellIndex::new(min_len, rare_max, common_min);
            ix.build(&refs);
            Ok(spell_index_output(&ix, top))
        }
        "spellIndexRebuild" => {
            let spec = input.first().unwrap_or(&Value::Null);
            let (min_len, rare_max, common_min, top) = spell_params(spec);
            let first = corpus_of(spec, "first");
            let second = corpus_of(spec, "second");
            let mut ix = spellfix::SpellIndex::new(min_len, rare_max, common_min);
            let frefs: Vec<&str> = first.iter().map(String::as_str).collect();
            ix.build(&frefs);
            let srefs: Vec<&str> = second.iter().map(String::as_str).collect();
            ix.build(&srefs);
            Ok(spell_index_output(&ix, top))
        }
        _ => Err(format!("unknown spellfix fn `{fname}`")),
    }
}

// -------------------------------------------------------------------- state

fn dispatch_state(fname: &str, input: &[Value]) -> Result<Value, String> {
    match fname {
        "_probe_pyFloatRepr" => Ok(json!(state::py_float_repr(f64_of(
            input.first().unwrap_or(&Value::Null)
        )))),
        "pyJsonStringify" => {
            let value = input.first().unwrap_or(&Value::Null);
            let opts = input.get(1).unwrap_or(&Value::Null);
            let indent = match opts.get("indent") {
                Some(Value::Number(n)) => Some(n.as_i64().unwrap_or(0)),
                _ => None,
            };
            let sort_keys = opts
                .get("sortKeys")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            Ok(json!(state::py_json_stringify(
                value,
                state::JsonOpts { indent, sort_keys }
            )))
        }
        "dumpsSorted" => Ok(json!(state::dumps_sorted(
            input.first().unwrap_or(&Value::Null)
        ))),
        "emptyState" => Ok(state::empty_state()),
        "DEFAULT_STATE_PATH" => {
            let home = input.first().and_then(Value::as_str).unwrap_or("");
            Ok(json!(state::resolve_state_path(None, None, home)))
        }
        "resolveStatePath" => {
            let explicit = match input.first() {
                Some(Value::String(s)) => Some(s.as_str()),
                _ => None,
            };
            let env = match input.get(1) {
                Some(Value::String(s)) => Some(s.as_str()),
                _ => None,
            };
            let home = input.get(2).and_then(Value::as_str).unwrap_or("");
            Ok(json!(state::resolve_state_path(explicit, env, home)))
        }
        _ => Err(format!("unknown state fn `{fname}`")),
    }
}

